<template><CrudShell title="Quản lý admin users" :loading="loading" :error="error" @create="openCreate" @reload="load"><template #form v-if="editing"><form class="grid gap-3 rounded-3xl border bg-white p-4 md:grid-cols-3" @submit.prevent="save"><input v-model="form.name" class="rounded-xl border p-3" placeholder="Name"><input v-model="form.email" class="rounded-xl border p-3" placeholder="Email"><input v-model="form.password" type="password" class="rounded-xl border p-3" placeholder="Password optional"><input v-model="form.role" class="rounded-xl border p-3" placeholder="Role"><select v-model="form.status" class="rounded-xl border p-3"><option>ACTIVE</option><option>INACTIVE</option></select><div class="flex gap-2 md:col-span-3"><button class="rounded-xl bg-slate-950 px-4 py-2 font-bold text-white">Save</button><button type="button" class="rounded-xl border px-4 py-2" @click="editing = null">Cancel</button></div></form></template><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Name</th><th>Email</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-b"><td class="p-3 font-bold">{{ row.name }}</td><td>{{ row.email }}</td><td>{{ row.role }}</td><td>{{ row.status }}</td><td class="space-x-2 text-right"><button class="font-bold" @click="openEdit(row)">Edit</button><button class="font-bold text-red-600" @click="remove(row.id)">Delete</button></td></tr></tbody></table></CrudShell></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import CrudShell from '@/pages/admin/CrudShell.vue'; import { adminUserApi } from '@/modules/customer/api'; import { getErrorMessage } from '@/modules/shared/hooks'; import type { AdminUser, AdminUserPayload } from '@/modules/customer/types'
const rows = ref<AdminUser[]>([]); const loading = ref(false); const error = ref(''); const editing = ref<AdminUser | 'new' | null>(null); const form = reactive<AdminUserPayload>({ name: '', email: '', password: '', role: 'ADMIN', status: 'ACTIVE' })
function fill(r?: AdminUser) { Object.assign(form, { name: r?.name || '', email: r?.email || '', password: '', role: r?.role || 'ADMIN', status: r?.status || 'ACTIVE' }) } function openCreate() { editing.value = 'new'; fill() } function openEdit(r: AdminUser) { editing.value = r; fill(r) } async function load() { loading.value = true; try { rows.value = (await adminUserApi.list({ limit: 50 })).items } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } } async function save() { const payload = { ...form }; if (!payload.password) delete payload.password; try { if (editing.value === 'new') await adminUserApi.create(payload); else if (editing.value) await adminUserApi.update(editing.value.id, payload); editing.value = null; await load() } catch (e) { error.value = getErrorMessage(e) } } async function remove(id: string) { if (!confirm('Delete user?')) return; await adminUserApi.remove(id); await load() } onMounted(load)
</script>
